cat > /tmp/scan3.py << 'PYEOF'
import re
files = open('/tmp/filelist.txt').read().split()
sig_re = re.compile(r'^\s*(?:@\w+(?:\([^)]*\))?\s*)*(?:(?:public|protected|private|static|final|abstract|synchronized|default)\s+)+(?:<[^>]*>\s*)?[\w.<>\[\],?@ ]+?\s+(\w+)\s*\(')
bad_names = {'if','for','while','switch','catch','synchronized','new','return'}
for fn in files:
    try:
        lines = open(fn).read().split('\n')
    except FileNotFoundError:
        print("MISSING", fn); continue
    current = None
    hits = {}
    for line in lines:
        m = sig_re.match(line)
        if m and m.group(1) not in bad_names and 'class ' not in line and '=' not in line.split('(')[0]:
            current = m.group(1)
        if 'delegate()' in line:
            hits[current] = hits.get(current, 0) + 1
    print(fn + " :: " + ", ".join(sorted(k for k in hits if k)))
PYEOF
python3 /tmp/scan3.py

